      <Card className="span-2"><SectionTitle title="Próximas aulas" action={<button className="text-link" onClick={() => navigate("atividades")}>Ver planejamento</button>} /><div className="schedule-list"><div><time>08:00</time><i className="purple"/><span><strong>5101 · Matemática</strong><small>Medidas e estimativas · Sala 12</small></span><StatusBadge status="Pronto"/></div><div><time>10:20</time><i className="orange"/><span><strong>6101 · Matemática</strong><small>Frações equivalentes · Sala 8</small></span><Badge tone="warning">Ajustar</Badge></div><div><time>14:10</time><i className="gold"/><span><strong>6201 · Matemática</strong><small>Plano cartesiano · Laboratório</small></span><StatusBadge status="Pronto"/></div></div></Card>
