function AssistantPage({ profile, navigate, addToast, loading, setLoading }: PageProps) {
  const [prompt, setPrompt] = useState("");
  const [context, setContext] = useState("Turma 6101");
  const [messages, setMessages] = useState<Array<{ role: "user" | "assistant"; text: string }>>([
    { role: "assistant", text: `Olá, ${profile.name.split(" ")[0]}! Posso ajudar a transformar o contexto pedagógico em um rascunho claro e revisável. Por onde começamos?` },
  ]);
  const [processStep, setProcessStep] = useState("");
  const send = async (value = prompt) => {
    if (!value.trim() || loading) return;
    setMessages((items) => [...items, { role: "user", text: value }]); setPrompt(""); setLoading(true);
    for (const step of ["Consultando o contexto autorizado...", "Organizando objetivos e evidências...", "Preparando um rascunho revisável..."]) { setProcessStep(step); await simulate(null, 430); }
    const response = value.toLowerCase().includes("reuni")
      ? "Preparei uma pauta para a reunião: 1) acolhimento e objetivo; 2) pontos fortes observados; 3) evidências recentes; 4) estratégias já aplicadas; 5) combinados e data de revisão. Mantive fatos separados de interpretações."
      : value.toLowerCase().includes("quest")
      ? "Criei uma questão de Matemática para o 6º ano alinhada à EF06MA07, com contexto de receita e quatro alternativas. A habilidade, a dificuldade e os distratores estão sinalizados para sua revisão."
      : "Organizei um plano de 50 minutos sobre frações equivalentes: aquecimento com estimativas, investigação em duplas, sistematização com representações visuais e bilhete de saída. Incluí apoio de leitura sem alterar o objetivo de aprendizagem.";
    setMessages((items) => [...items, { role: "assistant", text: response }]); setLoading(false); setProcessStep("");
  };
  return <div className="assistant-page animate-in"><PageHeader eyebrow="Copiloto pedagógico" title="Assistente IA" description="Converse com o contexto que você escolher. Nada é aplicado sem sua revisão." actions={<Button variant="secondary" icon={Plus} onClick={() => setMessages([])}>Nova conversa</Button>} breadcrumbs={["Assistente IA"]}/>
    <div className="assistant-layout"><aside className="conversation-sidebar"><SectionTitle title="Conversas" action={<IconButton label="Nova conversa" icon={Plus}/>} /><SearchInput value="" onChange={() => {}} placeholder="Buscar conversas"/><div className="conversation-list"><button className="active"><span><MessageSquareText size={17}/><strong>Plano de retomada · 6101</strong></span><small>Hoje</small></button><button><span><MessageSquareText size={17}/><strong>Reunião com família</strong></span><small>Ontem</small></button><button><span><MessageSquareText size={17}/><strong>Variações de questões</strong></span><small>12 jul.</small></button></div></aside>
      <section className="chat-panel"><div className="chat-context-bar"><div><span>Contexto ativo</span><label><Network size={16}/><select value={context} onChange={(e) => setContext(e.target.value)}><option>Turma 6101</option><option>Instituição</option><option>Ana Clara Souza</option><option>Avaliação de números racionais</option><option>Proposta pedagógica 2026</option></select><ChevronDown size={14}/></label></div><Badge tone="success">Contexto autorizado</Badge></div>
        <div className="chat-messages">{messages.length === 0 && <EmptyState icon={Bot} title="Nova conversa" text="Escolha uma sugestão ou escreva o que precisa organizar." />}{messages.map((message, index) => <div key={index} className={cx("message", `message-${message.role}`)}>{message.role === "assistant" && <span className="bot-avatar"><Bot size={18}/></span>}<div><p>{message.text}</p>{message.role === "assistant" && index > 0 && <div className="message-actions"><button onClick={() => addToast("Modo de edição", "O conteúdo pode ser ajustado antes de salvar.", "info")}><Edit3/>Editar</button><button onClick={() => { navigator.clipboard?.writeText(message.text); addToast("Copiado"); }}><Copy/>Copiar</button><button onClick={() => addToast("Rascunho salvo", "Disponível em Atividades e aulas.")}><Save/>Salvar</button><button onClick={() => navigate("atividades")}><ClipboardList/>Transformar em atividade</button><button onClick={() => send("Gere outra opção para a solicitação anterior")}><RefreshCw/>Gerar outra opção</button></div>}</div></div>)}{loading && <div className="message message-assistant"><span className="bot-avatar"><Bot size={18}/></span><div className="thinking"><span><i/><i/><i/></span><p>{processStep}</p></div></div>}</div>
        <div className="quick-prompts">{quickCommands.slice(0,5).map((item) => <button key={item} onClick={() => send(item)}>{item}</button>)}</div>
        <form className="chat-input" onSubmit={(e) => { e.preventDefault(); send(); }}><textarea value={prompt} onChange={(e) => setPrompt(e.target.value)} placeholder="Peça um plano, atividade, questão, adaptação ou síntese..." rows={2}/><div><span><ShieldCheck size={14}/>Revise antes de utilizar.</span><Button type="submit" icon={Send} disabled={!prompt.trim() || loading}>Enviar</Button></div></form>
      </section><aside className="context-panel"><SectionTitle title="Contexto considerado"/><div className="context-card"><span><GraduationCap/></span><div><strong>Turma 6101</strong><small>6º ano · 29 estudantes</small></div><CheckCircle2/></div><div className="context-block"><h3>Habilidades prioritárias</h3><p><Badge tone="warning">EF06MA07</Badge> Frações equivalentes</p><p><Badge tone="orange">EF06MA11</Badge> Números racionais</p></div><div className="context-block"><h3>Documentos usados</h3><p><FileText size={15}/>Proposta pedagógica 2026</p><p><FileText size={15}/>Diretrizes de avaliação</p></div><div className="privacy-note"><ShieldCheck/><p><strong>Contexto sob seu controle</strong><span>Somente os itens indicados apoiam esta conversa.</span></p></div></aside></div></div>;
}

function ClassesPage({ profile, navigate, openCreate }: PageProps & { openCreate: () => void }) {
  const [query, setQuery] = useState(""); const [segment, setSegment] = useState("Todos"); const [shift, setShift] = useState("Todos"); const [view, setView] = useState<"cards" | "table">("cards");
  const filtered = classes.filter((item) => (!profile.classes.length || profile.classes.includes(item.code)) && (segment === "Todos" || item.segment === segment) && (shift === "Todos" || item.shift === shift) && `${item.code} ${item.subject} ${item.teacher}`.toLowerCase().includes(query.toLowerCase()));
  return <div className="page animate-in"><PageHeader eyebrow="Organização pedagógica" title="Turmas" description="Visualize indicadores, planejamentos e evidências de aprendizagem." breadcrumbs={["Turmas"]} actions={<Button icon={Plus} onClick={openCreate}>Criar turma</Button>}/>
    <div className="toolbar"><SearchInput value={query} onChange={setQuery} placeholder="Pesquisar turma ou professor"/><div className="filters"><label><Filter size={15}/><select value={segment} onChange={(e) => setSegment(e.target.value)}><option>Todos</option><option>Anos Iniciais</option><option>Anos Finais</option></select></label><label><select value={shift} onChange={(e) => setShift(e.target.value)}><option>Todos</option><option>Manhã</option><option>Tarde</option></select></label></div><div className="view-toggle"><IconButton label="Cards" icon={Grid2X2} active={view === "cards"} onClick={() => setView("cards")}/><IconButton label="Tabela" icon={List} active={view === "table"} onClick={() => setView("table")}/></div></div>
    {filtered.length === 0 ? <EmptyState icon={GraduationCap} title="Nenhuma turma encontrada" text="Ajuste os filtros ou crie uma nova turma."/> : view === "cards" ? <div className="class-grid">{filtered.map((item) => <Card key={item.id} className="class-card" onClick={() => navigate(`turmas/${item.id}`)}><div className="class-card-head"><span className="class-code">{item.code}</span><Badge tone={item.shift === "Manhã" ? "purple" : "orange"}>{item.shift}</Badge></div><h3>{item.year} · {item.subject}</h3><p>{item.teacher}</p><div className="class-stats"><div><strong>{item.students}</strong><span>alunos</span></div><div><strong>{item.average}</strong><span>média</span></div><div><strong>{item.attendance}%</strong><span>frequência</span></div></div><div className="class-next"><Clock3 size={15}/><span>Próxima aula: {item.nextClass}</span></div><div className="class-progress"><span>Habilidades consolidadas</span><Progress value={item.skills.filter((s) => s.level === "consolidada").length * 33}/></div><button className="card-link">Abrir turma <ArrowRight size={15}/></button></Card>)}</div> : <div className="table-card"><table><thead><tr><th>Turma</th><th>Segmento</th><th>Disciplina</th><th>Professor</th><th>Alunos</th><th>Média</th><th>Frequência</th><th/></tr></thead><tbody>{filtered.map((item) => <tr key={item.id}><td><strong>{item.code}</strong><small>{item.year} · {item.shift}</small></td><td>{item.segment}</td><td>{item.subject}</td><td>{item.teacher}</td><td>{item.students}</td><td>{item.average}</td><td><Progress value={item.attendance} tone="green"/></td><td><IconButton label="Abrir turma" icon={ArrowRight} onClick={() => navigate(`turmas/${item.id}`)}/></td></tr>)}</tbody></table></div>}
  </div>;
}

function ClassDetail({ classId, data, navigate }: PageProps & { classId: string }) {
  const group = classes.find((item) => item.id === classId) || classes[0]; const [tab, setTab] = useState("geral");
  const classStudents = students.filter((s) => s.classId === group.id);
  const tabs = [{id:"geral",label:"Visão geral"},{id:"alunos",label:"Alunos",count:classStudents.length},{id:"habilidades",label:"Habilidades"},{id:"planejamentos",label:"Planejamentos"},{id:"atividades",label:"Atividades"},{id:"avaliacoes",label:"Avaliações"},{id:"observacoes",label:"Observações"},{id:"historico",label:"Histórico"}];
  return <div className="page animate-in"><button className="back-link" onClick={() => navigate("turmas")}><ArrowLeft/>Voltar para turmas</button><PageHeader eyebrow={`${group.segment} · ${group.shift}`} title={`Turma ${group.code}`} description={`${group.year} · ${group.subject} · ${group.teacher}`} breadcrumbs={["Turmas", group.code]} actions={<><Button variant="secondary" icon={FileText}>Relatório da turma</Button><Button icon={Plus} onClick={() => navigate("atividades/plano")}>Novo planejamento</Button></>}/><Tabs items={tabs} active={tab} onChange={setTab}/>
    {tab === "geral" && <div className="detail-grid"><div className="detail-main"><div className="metric-grid cols-3"><MetricCard label="Estudantes" value={group.students} detail="2 com acompanhamento ativo" icon={Users}/><MetricCard label="Média geral" value={group.average} detail="+0,4 no bimestre" icon={TrendingUp} tone="green"/><MetricCard label="Frequência" value={`${group.attendance}%`} detail="acima da meta de 90%" icon={CalendarDays} tone="orange"/></div><Card><SectionTitle title="Mapa pedagógico" description="Evidências consolidadas das atividades e avaliações" action={<Button size="sm" variant="ghost">Ver relatório</Button>}/><div className="pedagogical-map">{group.skills.map((skill) => <div key={skill.code}><span className={cx("skill-status", `skill-${skill.level}`)}>{skill.level === "consolidada" ? <CheckCircle2/> : skill.level === "desenvolvimento" ? <TrendingUp/> : <RotateCcw/>}</span><div><strong>{skill.code} · {skill.label}</strong><small>{skill.level === "consolidada" ? "Consolidada" : skill.level === "desenvolvimento" ? "Em desenvolvimento" : "Precisa ser retomada"}</small></div><Progress value={skill.score} tone={skill.level === "consolidada" ? "green" : skill.level === "retomar" ? "orange" : "purple"} label={`${skill.score}%`}/></div>)}</div></Card><Card><SectionTitle title="Desempenho recente"/><div className="chart-box"><ResponsiveContainer width="100%" height={220}><LineChart data={[{a:"Ativ. 1",v:62},{a:"Ativ. 2",v:68},{a:"Prova",v:65},{a:"Lista",v:74},{a:"Projeto",v:79}]}><CartesianGrid strokeDasharray="3 3" vertical={false}/><XAxis dataKey="a" axisLine={false} tickLine={false}/><YAxis domain={[40,100]} axisLine={false} tickLine={false}/><Tooltip/><Line dataKey="v" stroke="#462984" strokeWidth={3}/></LineChart></ResponsiveContainer></div></Card></div><aside className="detail-aside"><Card><SectionTitle title="Próximos compromissos"/><div className="event-list"><div><span>17<small>JUL</small></span><p><strong>Aula · Frações</strong><small>Hoje, 10h20</small></p></div><div><span>24<small>JUL</small></span><p><strong>Avaliação bimestral</strong><small>60 min</small></p></div><div><span>31<small>JUL</small></span><p><strong>Conselho de classe</strong><small>14h</small></p></div></div></Card><Card className="suggestion-card"><div><span><Sparkles/></span><Badge tone="purple">Oportunidade</Badge></div><h3>Grupo de retomada</h3><p>6 estudantes tiveram dificuldade recorrente em números racionais.</p><Button variant="secondary" onClick={() => navigate("atividades")}>Criar atividade</Button></Card></aside></div>}
    {tab === "alunos" && <Card><SectionTitle title="Estudantes da turma"/><div className="student-list-table">{classStudents.map((student) => <button key={student.id} onClick={() => navigate(`alunos/${student.id}`)}><span className="student-avatar">{student.initials}</span><div><strong>{student.name}</strong><small>{student.strength}</small></div><span>{student.attendance}% frequência</span><StatusBadge status={student.followUp}/><ArrowRight/></button>)}</div></Card>}
    {tab === "habilidades" && <Card><SectionTitle title="Habilidades da turma" description="Clique em uma habilidade para abrir as evidências."/><div className="skill-cards">{group.skills.map((skill) => <button key={skill.code}><div><Badge tone={skill.level === "consolidada" ? "success" : skill.level === "retomar" ? "orange" : "purple"}>{skill.code}</Badge><strong>{skill.label}</strong></div><Progress value={skill.score} tone={skill.level === "retomar" ? "orange" : "purple"} label="Domínio"/><small>12 evidências · última atualização há 3 dias</small></button>)}</div></Card>}
    {tab === "planejamentos" && <ModuleMiniList items={data.lessonPlans.filter((p) => p.classCode === group.code)} empty="Nenhum planejamento para esta turma." navigate={() => navigate("atividades/plano")}/>} {tab === "atividades" && <ModuleMiniList items={data.lessonPlans.filter((p) => p.classCode === group.code)} empty="Nenhuma atividade para esta turma." navigate={() => navigate("atividades")}/>} {tab === "avaliacoes" && <ModuleMiniList items={data.assessments.filter((a) => a.classCode === group.code)} empty="Nenhuma avaliação para esta turma." navigate={() => navigate("avaliacoes")}/>} {tab === "observacoes" && <Card><EmptyState icon={MessageSquareText} title="Observações reunidas nos Passaportes" text="Abra um estudante para registrar fatos, ações e resultados com o contexto adequado." action={<Button onClick={() => setTab("alunos")}>Ver estudantes</Button>}/></Card>} {tab === "historico" && <Card><div className="timeline"><div><i/><span><strong>Avaliação bimestral criada</strong><small>Mariana Costa · há 2 dias</small></span></div><div><i/><span><strong>Mapa de habilidades atualizado</strong><small>Sistema demonstrativo · há 4 dias</small></span></div><div><i/><span><strong>Plano de aula aplicado</strong><small>Mariana Costa · 8 jul. 2026</small></span></div></div></Card>}
  </div>;
}

function ModuleMiniList({ items, empty, navigate }: { items: Array<Assessment | LessonPlan>; empty: string; navigate: () => void }) {
  if (!items.length) return <Card><EmptyState title="Nada por aqui ainda" text={empty} action={<Button onClick={navigate}>Criar agora</Button>}/></Card>;
  return <Card><div className="module-mini-list">{items.map((item) => <button key={item.id} onClick={navigate}><span className="list-icon"><FileText/></span><div><strong>{"name" in item ? item.name : item.title}</strong><small>{item.subject} · {"date" in item ? item.date : ""}</small></div><StatusBadge status={item.status}/><ArrowRight/></button>)}</div></Card>;
}

function StudentsPage({ profile, navigate }: PageProps) {
  const [query, setQuery] = useState(""); const [follow, setFollow] = useState("Todos"); const [classCode, setClassCode] = useState("Todas");
  const filtered = students.filter((item) => (profile.role !== "professor" || profile.classes.includes(item.classCode)) && (follow === "Todos" || item.followUp === follow) && (classCode === "Todas" || item.classCode === classCode) && `${item.name} ${item.classCode} ${item.strength}`.toLowerCase().includes(query.toLowerCase()));
  return <div className="page animate-in"><PageHeader eyebrow="Passaportes de Aprendizagem" title="Alunos" description="Acompanhe cada aprendizagem a partir de evidências, estratégias e próximos passos." breadcrumbs={["Alunos"]} actions={<Button variant="secondary" icon={Download}>Exportar lista</Button>}/><div className="toolbar"><SearchInput value={query} onChange={setQuery} placeholder="Pesquisar aluno ou habilidade"/><div className="filters"><label><select value={classCode} onChange={(e) => setClassCode(e.target.value)}><option>Todas</option>{classes.map((c) => <option key={c.code}>{c.code}</option>)}</select></label><label><select value={follow} onChange={(e) => setFollow(e.target.value)}><option>Todos</option><option>Ativo</option><option>Atenção</option><option>Sem acompanhamento</option></select></label></div></div><div className="student-cards">{filtered.map((student) => <Card key={student.id} className="student-card" onClick={() => navigate(`alunos/${student.id}`)}><div className="student-card-top"><span className="student-avatar large">{student.initials}</span><div><h3>{student.name}</h3><p>Turma {student.classCode}</p></div><StatusBadge status={student.followUp}/></div><div className="student-metrics"><div><strong>{student.average}</strong><span>Média</span></div><div><strong>{student.attendance}%</strong><span>Frequência</span></div></div><div className="student-skill"><span>Ponto forte</span><strong>{student.strength}</strong></div><div className="student-skill"><span>Em desenvolvimento</span><strong>{student.developing}</strong></div><button className="card-link">Abrir passaporte <ArrowRight/></button></Card>)}</div></div>;
}

